def test_xss_onclick_handler_removed() -> None:
    """onclick and other on* event handlers are removed from elements."""
    html = '<p><a href="https://example.com" onclick="alert(\'xss\')">Click me</a></p><button onmouseover="steal_data()">Hover me</button>'

    result = convert(html)
    assert result.content is not None and (not hasattr(result.content, "__len__") or len(result.content) > 0)
    assert result.content is not None
    assert "Click me" in result.content
    assert result.content is None or "onclick" not in result.content
    assert result.content is None or "onmouseover" not in result.content
    assert result.content is None or "alert(" not in result.content
    assert result.content is None or "steal_data" not in result.content


